std::string
sc_gui_path_name(const std::string &path) {
    std::string p = path;
    while (p.size() > 1 && p.back() == '/') {
        p.pop_back();
    }
    size_t pos = p.find_last_of('/');
    return pos == std::string::npos ? p : p.substr(pos + 1);
}

ImVec2
operator+(ImVec2 a, ImVec2 b) {
    return ImVec2(a.x + b.x, a.y + b.y);
}

bool
point_in_rect(float x, float y, const SDL_FRect *r) {
    return r && x >= r->x && x < r->x + r->w && y >= r->y && y < r->y + r->h;
}

// Keep SDL text input always enabled: scrcpy relies on SDL_EVENT_TEXT_INPUT
// to inject text into the device, so ImGui must never stop it
void
set_ime_data(ImGuiContext *, ImGuiViewport *viewport,
             ImGuiPlatformImeData *data) {
    SDL_Window *window = (SDL_Window *) viewport->PlatformHandleRaw;
    if (!window || !data->WantVisible) {
        return;
    }
    SDL_Rect r;
    r.x = (int) data->InputPos.x;
    r.y = (int) data->InputPos.y;
    r.w = 1;
    r.h = (int) data->InputLineHeight;
    SDL_SetTextInputArea(window, &r, 0);
}

struct Device {
    std::string serial;
    std::string model;
    std::string state;
    bool tcpip;

    const std::string &name() const { return model.empty() ? serial : model; }
    bool ready() const { return state == "device"; }
};

struct FileItem {
    std::string name;
    std::string mtime;
    uint64_t size;
    sc_gui_file_type type;

    // Symlinks are opened as directories (most links on Android are)
    bool is_dir() const {
        return type == SC_GUI_FILE_DIRECTORY || type == SC_GUI_FILE_LINK;
    }
};

struct AppItem {
    std::string name;
    std::string package;
    bool system;
};

struct Transfer {
    uint32_t id;
    sc_gui_transfer_type type;
    std::string name;
    sc_gui_transfer_state state;
    std::string detail;

    bool active() const {
        return state == SC_GUI_TRANSFER_PENDING
            || state == SC_GUI_TRANSFER_RUNNING;
    }
};

struct LogLine {
    std::string time; // "HH:MM:SS"
    sc_gui_log_level level;
    std::string text;
};

constexpr size_t LOG_MAX_LINES = 1000;
constexpr float LOG_HEADER_HEIGHT = 34.f;
constexpr float LOG_EXPANDED_HEIGHT = 220.f;

struct Toast {
    sc_gui_toast_level level;
    std::string text;
    Uint64 expire; // SDL_GetTicks() deadline
};

